package net.sf.jiga.xtended.ui;/**    This interface defines an appropriate scheme for a class that requires a stepper.*/	public interface Steppable {		/** Returns current step index */				public int getCurrentStep();		/** Returns total steps number */		public int getSteps();		/** Switches to next step state */		public void nextStep();		/** Switches to previous step state */		public void previousStep();		/** Resets to starting step state */		public void startStep();			}